package analysis

import (
	"math"
	"testing"
)

const nan = -1 // marker in test tables, replaced by NaN

func series(vals ...float64) []float64 {
	out := make([]float64, len(vals))
	for i, v := range vals {
		if v == nan {
			out[i] = math.NaN()
		} else {
			out[i] = v
		}
	}
	return out
}

func seconds(n int, step int64) []int64 {
	t := make([]int64, n)
	for i := range t {
		t[i] = int64(i) * step
	}
	return t
}

func near(a, b float64) bool { return math.Abs(a-b) < 1e-6 }

func TestFastestDistanceInterpolates(t *testing.T) {
	// 10 m/s for 100 s, then 20 m/s for 50 s.
	n := 151
	tt := seconds(n, 1)
	d := make([]float64, n)
	for i := 1; i < n; i++ {
		v := 10.0
		if i > 100 {
			v = 20
		}
		d[i] = d[i-1] + v
	}
	sec, w, ok := FastestDistance(tt, d, 1000)
	if !ok || !near(sec, 50) || !near(w.EndS, 150) || !near(w.StartS, 100) {
		t.Errorf("1 km: %v %+v %v", sec, w, ok)
	}
	// 1500 m: best is the last 1000 m at 20 m/s plus 500 m at 10 m/s = 100 s.
	if sec, _, _ := FastestDistance(tt, d, 1500); !near(sec, 100) {
		t.Errorf("1.5 km: %v", sec)
	}
	if _, _, ok := FastestDistance(tt, d, 5000); ok {
		t.Error("longer than the activity")
	}
	// Coarse recording: 10 m/s sampled every 7 s still gives 100 s for 1 km.
	tc := seconds(30, 7)
	dc := make([]float64, 30)
	for i := range dc {
		dc[i] = float64(i) * 70
	}
	if sec, _, _ := FastestDistance(tc, dc, 1000); !near(sec, 100) {
		t.Errorf("coarse: %v", sec)
	}
}

func TestFastestDistanceSkipsGapsAndBacksteps(t *testing.T) {
	tt := seconds(6, 10)
	// Dropout at 20 s and a GPS backstep at 30 s: the distance is held at
	// 100 m, so 100 → 300 m between 30 s and 40 s is the fastest 200 m.
	d := series(0, 100, nan, 50, 300, 400)
	sec, _, ok := FastestDistance(tt, d, 200)
	if !ok || !near(sec, 10) {
		t.Errorf("got %v %v", sec, ok)
	}
}

func TestPowerCurve(t *testing.T) {
	// 60 s at 200 W, 10 s at 500 W, 30 s pause (no records), then 60 s at 250 W.
	var tt []int64
	var p []float64
	for i := range 70 {
		tt = append(tt, int64(i))
		w := 200.0
		if i >= 60 {
			w = 500
		}
		p = append(p, w)
	}
	for i := range 60 {
		tt = append(tt, int64(100+i))
		p = append(p, 250)
	}
	c := PowerCurve(tt, p, []int{5, 10, 60, 120, 1000})
	if !near(c[5].Watts, 500) || !near(c[10].Watts, 500) || c[10].StartS != 60 {
		t.Errorf("short: %+v %+v", c[5], c[10])
	}
	// Best minute: 46 s at 200 W + 10 s at 500 W + 4 s of the 5 s hold into the pause.
	if !near(c[60].Watts, (46*200.0+14*500)/60) {
		t.Errorf("60 s: %+v", c[60])
	}
	// Two minutes must include zeros for the pause (held only 5 s).
	want := (50*200.0 + 10*500 + 5*500 + 55*0) / 120
	if got := c[120].Watts; got > 250 || got < want-1e-6 {
		t.Errorf("120 s: %v (at least %v)", got, want)
	}
	if _, ok := c[1000]; ok {
		t.Error("duration longer than the activity")
	}
	if PowerCurve(tt, series(nan, nan), []int{5}) != nil {
		t.Error("no power, no curve")
	}
}

func TestLargestClimb(t *testing.T) {
	tt := seconds(9, 60)
	alt := series(400, 450, 445, 520, 500, 480, 470, 500, 510)
	dist := series(0, 500, 600, 1500, 1700, 1900, 2000, 2300, 2400)
	c, ok := LargestClimb(tt, alt, dist)
	// 400 → 520 including the 5 m dip; the descent of 50 m ends it.
	if !ok || c.GainM != 120 || c.DistanceM != 1500 || c.StartS != 0 || c.EndS != 180 {
		t.Errorf("climb %+v %v", c, ok)
	}
	if _, ok := LargestClimb(tt, series(400, 410, 405, 420, 415, 400, 410, 400, 405), dist); ok {
		t.Error("20 m are no climb")
	}
}

func TestSplits(t *testing.T) {
	n := 251
	tt := seconds(n, 1)
	d := make([]float64, n)
	alt := make([]float64, n)
	hr := make([]float64, n)
	for i := range n {
		d[i] = float64(i) * 10 // 10 m/s → 2.5 km
		alt[i] = 400 + float64(i%2)
		hr[i] = 140
	}
	s := Splits(tt, d, alt, hr, nil, 1000)
	if len(s) != 3 {
		t.Fatalf("splits %d", len(s))
	}
	if s[0].DistanceM != 1000 || s[0].EndS != 100 || s[0].AvgHR != 140 || s[0].AvgPower != 0 {
		t.Errorf("first %+v", s[0])
	}
	if s[2].DistanceM != 500 || s[2].EndS != 250 {
		t.Errorf("rest %+v", s[2])
	}
	if s := Splits(tt, d[:105], nil, nil, nil, 1000); len(s) != 1 {
		t.Errorf("a 40 m rest is dropped: %d", len(s))
	}
}
